import data from '../../data/trackers.json';
import type { Category } from '../types';

interface TrackerData {
  source: string;
  domains: Record<string, [string, Category]>;
}

// Generated by scripts/update-trackers.mjs; JSON imports widen tuples to arrays.
const { domains } = data as unknown as TrackerData;

export interface TrackerMatch {
  companyId: string;
  category: Category;
}

/** Finds the tracker for a hostname, matching parent domains too: "a.b.doubleclick.net" → "doubleclick.net". */
export function lookupTracker(hostname: string): TrackerMatch | null {
  let host = hostname.toLowerCase();
  for (;;) {
    const hit = domains[host];
    if (hit) return { companyId: hit[0], category: hit[1] };
    const dot = host.indexOf('.');
    if (dot === -1) return null;
    host = host.slice(dot + 1);
  }
}

export { companyName } from './companies';
